package com.aistock.market.calendar;
import com.aistock.market.ingestion.CandidateRequestFilter;import com.aistock.common.ApiExceptionHandler;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class CalendarHttpTest {
 @Test void internalAuthAndStrictBoundedRequest()throws Exception{var service=mock(CalendarService.class);var mvc=MockMvcBuilders.standaloneSetup(new CalendarController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("fixture",2097152)).build();mvc.perform(get("/internal/v1/market/calendar")).andExpect(status().isUnauthorized());mvc.perform(post("/internal/v1/market/calendar/refresh").header("X-Service-Token","wrong").contentType("application/json").content("{")).andExpect(status().isUnauthorized());mvc.perform(post("/internal/v1/market/calendar/refresh").header("X-Service-Token","fixture").contentType("application/json").content("x".repeat(4097))).andExpect(status().isPayloadTooLarge());mvc.perform(post("/internal/v1/market/calendar/refresh").header("X-Service-Token","fixture").contentType("application/json").content("{\"operationId\":123,\"start\":\"2026-10-01\",\"end\":\"2026-11-01\"}")).andExpect(status().isBadRequest());verifyNoInteractions(service);mvc.perform(post("/internal/v1/market/calendar/refresh").header("X-Service-Token","fixture").contentType("application/json").content("{\"operationId\":\"calendar-test\",\"start\":\"2026-10-01\",\"end\":\"2026-11-01\"}")).andExpect(status().isOk());verify(service).refresh(any());}
 @Test void requestedCoverageIsSelectedWithoutChangingDefaultHeadAndMalformedQueriesFail()throws Exception{
 var service=mock(CalendarService.class);var mvc=MockMvcBuilders.standaloneSetup(new CalendarController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("fixture",2097152)).build();
 mvc.perform(get("/internal/v1/market/calendar?start=2025-10-09&end=2026-10-10")).andExpect(status().isUnauthorized());
 when(service.covering(java.time.LocalDate.parse("2025-10-09"),java.time.LocalDate.parse("2026-10-10"))).thenReturn(java.util.Optional.empty());
 mvc.perform(get("/internal/v1/market/calendar?start=2025-10-09&end=2026-10-10").header("X-Service-Token","fixture")).andExpect(status().isServiceUnavailable());
 verify(service).covering(java.time.LocalDate.parse("2025-10-09"),java.time.LocalDate.parse("2026-10-10"));verify(service,never()).current();
 var id=java.util.UUID.randomUUID();var candidate=new CalendarRecords.Candidate("baostock",java.time.LocalDate.parse("2025-10-09"),java.time.LocalDate.parse("2026-10-10"),java.time.Instant.parse("2026-10-10T06:00:00Z"),"a".repeat(64),java.util.List.of());
 when(service.covering(java.time.LocalDate.parse("2025-10-09"),java.time.LocalDate.parse("2026-10-10"))).thenReturn(java.util.Optional.of(new CalendarRecords.Snapshot(id,candidate)));
 mvc.perform(get("/internal/v1/market/calendar?start=2025-10-09&end=2026-10-10").header("X-Service-Token","fixture")).andExpect(status().isOk()).andExpect(jsonPath("$.data.versionId").value(id.toString()));

 for(String query:java.util.List.of("start=2026-10-10","start=2026-10-10&end=2026-10-09","start=2025-01-01&end=2026-10-10","start=x&end=2026-10-10","start=2026-10-09&start=2026-10-08&end=2026-10-10","other=x"))mvc.perform(get("/internal/v1/market/calendar?"+query).header("X-Service-Token","fixture")).andExpect(status().isBadRequest());
 }
}
